/bin/zsh -lc "/opt/homebrew/bin/python3 -c 'import importlib.util,pathlib,json,math,time; spec=importlib.util.spec_from_file_location(\"scan\", \"evidence/markov/scan.py\"); m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); t=time.monotonic(); cases=[]; fail=[]; counts={\"1\":0,\"2\":0,\"large\":0};
for path,(a,b,p) in m.generate(35):
 q,r=divmod(b,a)
 if a==1: e={k:k+1 for k in range(b)}
 elif a==2: e={q+1+k:4*(k+1) for k in range(q)}; e[2*q+1]=2*(q+1)
 else:
  e={}
  for k,c in enumerate([4*(a*k+r) for k in range(q)]+[3*b-1,a+b-1]):
   for z in range(a-2): e[b-q+k+z]=e.get(b-q+k+z,0)+c*math.comb(a-3,z)
 e={j:c for j,c in e.items() if c}; act={j:c for (i,j),c in p.items() if i==1}; counts[str(a) if a<3 else \"large\"]+=1
 if e"'!=act: fail.append({"a":a,"b":b,"expected":e,"actual":act})
pathlib.Path("evidence/markov-274e6973/all-first-vertical-experiment.json").write_text(json.dumps({"counts":counts,"failures":fail,"bound":35,"seconds":time.monotonic()-t,"status":"finite exact test only"},indent=2)); print(counts,len(fail))'"'"

